document.addEventListener('input',e=>{if(e.target.matches('input[data-amount]'))formatAmountInput(e.target);},true);
function onInput(e){const el=e.target,k=el.id;let rebuild=false;
 if(k==='unknown'){unknown=el.value;rebuild=true;}
 else if(k==='withdrawalEntry'){state.withdrawalMode=el.value==='dollars'?'dollars':state.percentageBasis||'starting';rebuild=true;}
 else if(k==='withdrawalBasis'){state.percentageBasis=el.value;state.withdrawalMode=el.value;rebuild=true;}
 else if(k==='adjustWithdrawals')state.adjustWithdrawals=el.value==='yes';
 else if(k==='horizonSlider'){state.years=readNumber(el.value);syncTime(k);}
 else if(k==='returnInput')state.nominal=el.value===''?null:readNumber(el.value)/100;
 else if(k==='targetAge'){state.years=yearsToAge(state.age,readNumber(el.value));syncTime(k);}
 else if(k==='age'){const target=readNumber($('#targetAge')?.value);state.age=readNumber(el.value);state.years=yearsToAge(state.age,target);syncTime(k);}
 else if(['cashMode','cashStrategy'].includes(k)){state[k]=el.value;rebuild=k==='cashMode';}
 else if(k in state){state[k]=el.value===''?null:readNumber(el.value)/(['inflation','fiRate','cashNominal','withdrawalRate'].includes(k)?100:1);if(k==='years'||k==='age')syncTime(k);}
 else return;
 riskOutput=null;update();if(rebuild)rebuildInputs();else syncSolved();persist();
}
function syncTime(active=''){
 const values={horizonSlider:state.years??0,years:entry(state.years,1,3),targetAge:enteredAge()};
 for(const [key,value] of Object.entries(values))if(key!==active&&$('#'+key))$('#'+key).value=$('#'+key).disabled&&key!=='horizonSlider'?'':value;
}
function syncSolved(){const p=resolveWithdrawals(state);
 if($('#fi-target-preview'))$('#fi-target-preview').textContent=Number.isFinite(p.fiWithdrawals)&&p.fiWithdrawals>0&&Number.isFinite(p.fiRate)&&p.fiRate>0?money(fiTarget(p)):'—';
 if($('#withdrawal-summary'))$('#withdrawal-summary').textContent=(state.withdrawalMode==='dollars'?money(p.spending)+' per year · '+money(p.spending/12)+' per month':percent(state.withdrawalRate)+' = '+money(p.spending)+' in the first year · '+money(p.spending/12)+' per month')+(state.withdrawalMode==='annual'?'. Recalculated from each year’s opening investment balance.':state.withdrawalMode==='starting'?'. Based on starting investments; the dollar amount follows your inflation choice.':'. Amount needed after income you already earn.');
 if(unknown==='spending'&&$('#withdrawal-summary'))$('#withdrawal-summary').textContent='';
 if($('#monthly'))$('#monthly').textContent=Number.isFinite(p.spending)?money(p.spending/12):'—';
 if(unknown==='portfolio'&&state.withdrawalMode!=='dollars'&&$('#withdrawal-summary'))$('#withdrawal-summary').textContent=percent(state.withdrawalRate)+' of the calculated investments shown in the results'+(state.withdrawalMode==='annual'?', recalculated each year.':'. The dollar amount follows your inflation choice.');
 if($('#real-summary'))$('#real-summary').textContent=unknown==='return'?'':percent(expectedReturn(p))+' real return after inflation';
 if($('#cash-equivalent'))$('#cash-equivalent').textContent=unknown==='spending'?(p.cashMode==='years'?'Cash amount follows the calculated withdrawals.':money(p.cash)):money(cashAmount(p))+' · '+(p.spending?num(cashAmount(p)/p.spending,2)+' years of withdrawals':'no withdrawals entered');
 if($('#cash-summary'))$('#cash-summary').textContent='· '+short(cashAmount(p));
}
function metric(label,value,detail='',progress){return `<div class="metric"><div class="label">${label}</div><div class="value">${value}</div><div class="detail">${detail}</div>${progress!==undefined?`<div class="progress"><span style="width:${Math.max(0,Math.min(100,progress*100))}%"></span></div>`:''}</div>`;}
function outcome(p){const s=solve(p,'time');return s.error?{error:s.error}:{years:s.value,date:dateLabel(s.value)};}
function timingNotice(p,q){const eventual=outcome(p);const funded=q.unfunded<.01;const hit=q.end.total>=q.target-.01&&funded;
 if(hit)return `<div class="notice good"><strong>${p.portfolio+cashAmount(p)>=q.target?'Total assets already meet the FI target.':`At or above your target by ${dateLabel(p.years)}.`}</strong> ${eventual.years!==undefined&&eventual.years>0?`First projected arrival: ${eventual.date}, in ${num(eventual.years,2)} years.`:''} This is a smooth-return projection.</div>`;
 return `<div class="notice"><strong>The plan misses ${dateLabel(p.years)}.</strong> ${eventual.years!==undefined?`At these assumptions, FI is projected in <strong>${eventual.date}</strong> (${num(eventual.years,2)} years from now), about <strong>${num(Math.max(0,eventual.years-p.years),2)} years later</strong> than your desired date.`:eventual.error} ${!funded?`Unfunded withdrawals by the desired date: ${money(displayAmount(q.unfunded,p,p.years))}.`:''}</div>`;
}
let charts=[],assetChartView='all';
function chart(id,rows,series,{percentAxis=false,marker=null,point=null,start=today,boundaries=[]}={}){
 const age=state.timeEntry==='age'&&Number.isFinite(state.age)&&['plan','gap','scenarios','withdrawals','dates'].includes(tab)?state.age:null;
 charts.push({id,rows,series,percentAxis,marker,point,start,age,boundaries});
 return `<div class="chart" id="${id}" aria-label="${id.replaceAll('-',' ')}"><svg role="img" aria-label="Interactive ${id.replaceAll('-',' ')}" viewBox="0 0 820 280"></svg><div class="chart-tip" hidden></div></div><div class="legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${s.label}</span>`).join('')}</div><p class="chart-caption">Hover, tap, or focus the chart and use the arrow keys to inspect a year.</p>`;
}
function drawCharts(){for(const c of charts){const wrap=$('#'+c.id);if(!wrap)continue;const svg=wrap.querySelector('svg'),W=820,H=280,L=65,R=15,T=20,B=36,maxX=Math.max(1,...c.rows.map(r=>r.year));
 const val=(r,key)=>{const v=r[key];return Number.isFinite(v)?v:0;};
 const maxY=Math.max(c.percentAxis?.01:1,...c.rows.flatMap(r=>c.series.map(s=>val(r,s.key))),c.point?.value||0)*1.12;
 const x=t=>L+t/maxX*(W-L-R),y=v=>H-B-v/maxY*(H-T-B);
 let html='';for(let i=0;i<=4;i++){const n=maxY*i/4;html+=`<line class="grid" x1="${L}" y1="${y(n)}" x2="${W-R}" y2="${y(n)}"/><text x="${L-12}" y="${y(n)+4}" text-anchor="end">${c.percentAxis?(n*100).toFixed(1)+'%':short(n)}</text>`;}
 for(let i=0;i<=5;i++){const t=maxX*i/5;html+=`<text x="${x(t)}" y="${H-9}" text-anchor="middle">${c.age!==null?'Age '+num(c.age+t):t===0?(c.start===today?'Today':'Start'):num(t)+'y'}</text>`;}
 c.series.forEach((s,i)=>{const d=c.rows.map((r,k)=>(k?'L':'M')+x(r.year)+','+y(val(r,s.key))).join(' ');if(i===0&&!c.percentAxis)html+=`<path d="${d} L${x(c.rows.at(-1).year)},${H-B} L${L},${H-B} Z" fill="${s.color}" opacity=".06"/>`;html+=`<path class="line" d="${d}" stroke="${s.color}" ${s.dash?'stroke-dasharray="7 6"':''}/>`;});
 for(const boundary of c.boundaries||[])if(boundary<maxX)html+=`<line x1="${x(boundary)}" x2="${x(boundary)}" y1="${T}" y2="${H-B}" stroke="var(--muted)" stroke-dasharray="2 6" opacity=".5"/>`;
 if(c.marker!==null&&c.marker<=maxX){html+=`<line x1="${x(c.marker)}" x2="${x(c.marker)}" y1="${T}" y2="${H-B}" stroke="var(--purple)" stroke-dasharray="3 5"/><text x="${Math.max(L+45,Math.min(W-55,x(c.marker)))}" y="13" text-anchor="middle">FI reached</text>`;}
 if(c.point)html+=`<circle cx="${x(c.point.year)}" cy="${y(c.point.value)}" r="6" fill="var(--red)" stroke="var(--surface)" stroke-width="3"/>`;
 html+='<line class="crosshair" y1="20" y2="244" stroke="var(--muted)" stroke-dasharray="2 4" visibility="hidden"/>';svg.innerHTML=html;svg.setAttribute('tabindex','0');
 let index=0;const show=i=>{index=Math.max(0,Math.min(c.rows.length-1,i));const r=c.rows[index],tip=wrap.querySelector('.chart-tip');tip.hidden=false;tip.innerHTML=`<strong>${c.age!==null?'Age '+num(c.age+r.year,2):'Year '+num(r.year,2)} · ${dateLabel(r.year,c.start)}</strong>`+c.series.map(s=>`<p>${s.label}: <strong>${c.percentAxis?percent(r[s.key]):money(r[s.key])}</strong></p>`).join('');const cross=svg.querySelector('.crosshair');cross.setAttribute('x1',x(r.year));cross.setAttribute('x2',x(r.year));cross.setAttribute('visibility','visible');};
 svg.onpointermove=e=>{const rect=svg.getBoundingClientRect(),t=Math.max(0,((e.clientX-rect.left)/rect.width*W-L)/(W-L-R)*maxX);show(c.rows.reduce((best,r,i)=>Math.abs(r.year-t)<Math.abs(c.rows[best].year-t)?i:best,0));};svg.onpointerleave=()=>{wrap.querySelector('.chart-tip').hidden=true;svg.querySelector('.crosshair').setAttribute('visibility','hidden');};svg.onfocus=()=>show(index);svg.onblur=svg.onpointerleave;svg.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();show(index+(e.key==='ArrowRight'?1:-1));}};
}}
function displayRows(rows,p){return rows.map(r=>{const f=nominal?Math.pow(1+p.inflation,r.year):1;const out={...r};for(const k of ['investment','cash','total','target','spending','income','beginning','investmentReturn','cashInterest','investmentWithdrawal','cashWithdrawal','unfunded'])out[k]*=f;return out;});}
const colors={investment:'var(--purple)',cash:'var(--red)',total:'var(--secondary)',target:'var(--muted)'};
const seriesMain=[{key:'investment',label:'Investments',color:colors.investment},{key:'cash',label:'Cash reserve',color:colors.cash},{key:'total',label:'Total assets',color:colors.total},{key:'target',label:'FI target',color:colors.target,dash:true}];
const displayAmount=(value,p,year)=>nominal?toNominal(value,p.inflation,year):value;
const dollarControls=()=>`<div class="section-head"><p>Results in ${nominal?'future dollars at each date':'today’s purchasing power'}</p><div class="segmented" aria-label="Result dollar format"><button data-dollars="real" class="${!nominal?'active':''}">Today’s dollars</button><button data-dollars="nominal" class="${nominal?'active':''}">Future dollars</button></div></div>`;
function table(q,p){const rs=displayRows(q.rows,p);return `<details class="panel table-details"><summary>Year-by-year projection · ${nominal?'future':'today’s'} dollars</summary><div class="table-scroll"><table><thead><tr>${['Year','Phase during period','Withdrawals requested','Withdrawals funded','Investments','Cash','Total assets','FI target','Unfunded'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr><td>${num(r.year,3)}${q.transitionAt!==null&&Math.abs(r.year-q.transitionAt)<1e-7?' · FI reached':''}</td><td>${r.year===0?'Starting point':r.phase}</td><td>${r.year===0?'—':money(r.spending)}</td><td>${r.year===0?'—':money(r.investmentWithdrawal+r.cashWithdrawal)}</td>${['investment','cash','total','target','unfunded'].map(k=>`<td>${money(r[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="chart-caption">Withdrawals are totals for each period. Partial years are prorated. Future-dollar amounts use each period’s ending date.</p></details>`;}
function projectionHorizon(p,id){const years=[...new Set([0,5,10,20,30,40,50,p.afterFIYears])].sort((a,b)=>a-b);return `<div class="field projection-horizon"><label for="${id}">Years to show after FI</label><select id="${id}" data-projection-horizon>${years.map(y=>`<option value="${y}" ${y===p.afterFIYears?'selected':''}>${y===0?'Stop at FI':y+' years'}</option>`).join('')}</select><small class="hint">Applies to both graphs and the year-by-year projection.</small></div>`;}
function planView(p,q,sol){
 const full=lifetimeProjection(p),arrival=outcome(p),at=arrival.years??p.years;
 q=project(p,{years:p.years,transitionAt:full.transitionAt});
 const amount=(v,y=p.years)=>money(displayAmount(v,p,y));
 let value,unit='',sub='';
 if(unknown==='projection'){value=q.end.total>=q.target-.01&&q.unfunded<.01?'On track for your date':'Not on track for your date';sub=`Total assets at your desired date: ${amount(q.end.total)}, against a ${amount(q.target)} target.`;}
 else if(unknown==='spending'){value=p.withdrawalMode==='dollars'?money(p.spending):percent(p.withdrawalRate);unit=p.withdrawalMode==='dollars'?'per year, in today’s dollars':p.withdrawalMode==='annual'?'of each year’s investments':'of starting investments';sub=`Initial annual withdrawal basis: ${money(p.spending)} in today’s dollars. ${p.adjustWithdrawals?'Dollar withdrawals rise with inflation.':'Dollar withdrawals stay fixed in future dollars.'}`;}
 else if(unknown==='portfolio'){value=money(p.portfolio);unit='invested today';sub=`Plus ${money(cashAmount(p))} cash. Both count toward FI.`;}
 else if(unknown==='time'){value=p.timeEntry==='age'?num(p.age+p.years,1):num(p.years,2);unit=p.timeEntry==='age'?'years old':'years';sub=dateLabel(p.years);}
 else {value=percent(nominalReturn(expectedReturn(p),p.inflation));unit='return before inflation';sub=`${percent(expectedReturn(p))} after inflation. A required assumption, not a forecast.`;}
 return `${dollarControls()}<div class="answer"><p class="eyebrow">${labels[unknown]||'Your plan'}</p><h2>${value} <small>${unit}</small></h2><p class="sub">${sub}</p></div>${timingNotice(p,q)}
 <div class="metrics">${metric('Traditional FI target',amount(q.target,at),`${money(q.target)} today = ${money(toNominal(q.target,p.inflation,at))} in ${dateLabel(at)}. Investments + cash.`)}${metric('Total assets at desired date',amount(q.end.total),dateLabel(p.years))}${metric('Annual withdrawals at FI',amount(traditionalWithdrawals(p),at),`${money(traditionalWithdrawals(p))} in today’s purchasing power; starts when FI is reached.`)}</div>
 <section class="panel content-panel plan-overview"><h3>Your plan at a glance</h3><p class="hint">Starting amounts are in today’s dollars.</p><div class="summary-groups">
 ${summaryGroup('Your assets',[
 ['Total assets',money(p.portfolio+cashAmount(p))],['Investments',money(p.portfolio)],['Cash reserve',money(cashAmount(p))],['Progress toward FI',percent((p.portfolio+cashAmount(p))/q.target)]])}
 ${summaryGroup('Your withdrawals',[
 ['Annual withdrawals',money(p.spending)],['Monthly equivalent',money(p.spending/12)],['Share of starting assets',percent(p.spending/(p.portfolio+cashAmount(p)))],['Withdrawal rule',p.withdrawalMode==='annual'?percent(p.withdrawalRate)+' of investments each year':(p.withdrawalMode==='starting'?percent(p.withdrawalRate)+' of starting investments · ':'')+(p.adjustWithdrawals?'Rises with inflation':'Fixed dollar amount')]])}
 ${summaryGroup('Your timeline',[
 ...(p.timeEntry==='age'?[['Starting age',num(p.age,1)]]:[]),[p.timeEntry==='age'?'Desired FI age':'Desired timeline',p.timeEntry==='age'?num(p.age+p.years,1):num(p.years,2)+' years'],['Desired date',dateLabel(p.years)],[p.timeEntry==='age'?'Projected FI age':'Projected time to FI',arrival.years===null?'Not reached':p.timeEntry==='age'?num(p.age+arrival.years,1):num(arrival.years,2)+' years'],['Projected date',arrival.years===null?'Not reached within projection':dateLabel(arrival.years)]])}
 ${summaryGroup('Your assumptions',[
 ['Return before inflation',percent(nominalReturn(expectedReturn(p),p.inflation))],['Inflation',percent(p.inflation)],['Return after inflation',percent(expectedReturn(p))],['Cash strategy',p.cashStrategy==='reserve'?'Reserve only':p.cashStrategy==='first'?'Spend cash first':'Market downturn buffer'],['Cash yield before inflation',percent(p.cashNominal)]])}
 </div></section>
 <div class="panel chart-panel"><h2>Your assets before and after FI</h2>${projectionHorizon(p,'asset-horizon')}${select('asset-chart-view','Show',{all:'All assets',cash:'Cash reserve only'},assetChartView)}<p>At FI, withdrawals switch to your Traditional FI amount. ${p.adjustWithdrawals?'That amount then rises with inflation.':'Its dollar amount is fixed from that date.'}</p>${chart('portfolio-trajectory',displayRows(full.rows,p),assetChartView==='cash'?seriesMain.filter(s=>s.key==='cash'):seriesMain,{marker:full.transitionAt})}<p class="chart-caption">${assetChartView==='cash'?'Cash reserve uses its own scale in this view.':'All lines share one dollar scale; smaller cash changes may look flat. Select Cash reserve only for a closer view.'} ${nominal?'Future dollars':'Today’s dollars'} · total assets determine FI. ${full.capped?'Projection capped at 100 years.':''} ${full.transitionAt===null?'No funded FI arrival was found; projection ends at your selected horizon.':''}</p></div>
 <div class="panel chart-panel"><h2>Withdrawals as a share of total assets</h2>${projectionHorizon(p,'withdrawal-horizon')}<p>Annual planned withdrawals divided by assets at the start of each period.</p>${chart('withdrawal-rates',full.rows.map(r=>({...r,withdrawalRate:r.year===0?p.spending/r.total:r.withdrawalRate,rateTarget:p.fiRate})),[{key:'withdrawalRate',label:'Withdrawals / total assets',color:colors.investment},{key:'rateTarget',label:'Selected FI rate',color:colors.target,dash:true}],{percentAxis:true,marker:full.transitionAt})}</div>
 ${full.unfunded>.01?`<div class="notice"><strong>Some projected withdrawals cannot be funded.</strong> See Unfunded in the table. Reaching the FI target does not guarantee the later withdrawals can be maintained.</div>`:''}${table(full,p)}<p class="chart-caption">Smooth-return projection. Compare return scenarios to see how different returns affect your plan.</p>`;
}
const comparisonOptions={withdrawals:{time:'FI date / age',portfolio:'Starting investments needed',return:'Return needed'},returns:{time:'FI date / age',portfolio:'Starting investments needed',spending:'Withdrawals available'},dates:{spending:'Withdrawals available',portfolio:'Starting investments needed',return:'Return needed'}};
function comparisonQuestion(kind){const choices=comparisonOptions[kind];return Object.hasOwn(choices,comparisonQuestions[kind])?comparisonQuestions[kind]:Object.hasOwn(choices,unknown)?unknown:kind==='dates'?'spending':'time';}
function comparisonSelector(kind,question){return select('compare-question-'+kind,'What do you want to compare?',comparisonOptions[kind],question);}
function targetDatesView(p){
 const question=comparisonQuestion('dates'),years=targetHorizons??[Math.max(1,p.years-5),Math.max(1,p.years),Math.min(100,Math.max(1,p.years)+5)],age=p.timeEntry==='age';
 const inputs=`<div class="panel content-panel"><h2>How does your target date change your plan?</h2>${comparisonSelector('dates',question)}<p>Your FI target stays ${money(fiTarget(p))} in today’s dollars. Starting cash, inflation and the other inputs stay fixed.</p><div class="scenario-controls">${years.map((y,i)=>field('targetScenario'+i,'Target '+(i+1)+(age?' age':''),age?(y===null?'':entry(p.age+y,1,2)):(y===null?'':dateValue(dateAfter(y))),age?{min:p.age,max:p.age+100}:{type:'date'})).join('')}</div><button id="target-defaults">Use plan defaults</button><p class="hint">Defaults: five years earlier, your plan’s target, and five years later. Editing comparisons does not change Your plan.</p></div>`;
 let result;try{result=compareTargetDates(p,years,question);}catch(e){return inputs+`<div class="notice" role="alert">${e.message}</div>`;}
 return inputs+`<h2 class="result-divider">Results</h2><div class="metrics">${result.scenarios.map((s,i)=>{const label=age?'Age '+num(p.age+s.years,2):dateLabel(s.years);if(s.error)return metric(label,'Not feasible',s.error);const value=question==='spending'?money(s.plan.spending):question==='portfolio'?money(s.plan.portfolio):percent(nominalReturn(expectedReturn(s.plan),p.inflation));return metric(label,value,question==='spending'?'Annual withdrawals in today’s dollars'+(s.plan.withdrawalMode!=='dollars'?' · '+percent(s.plan.withdrawalRate)+' withdrawal rate':''):question==='portfolio'?'Starting investments today, plus '+money(s.plan.cash)+' cash':'Required return before inflation · '+percent(expectedReturn(s.plan))+' real');}).join('')}</div><div class="panel content-panel"><h3>Your FI target at each date</h3><div class="metrics">${years.map(y=>metric(dateLabel(y),money(toNominal(fiTarget(p),p.inflation,y)),money(fiTarget(p))+" in today’s dollars")).join('')}</div><p>Each result uses its own target date. Required returns are assumptions, not forecasts.</p></div>`;
}
function scenariosView(p){
 const question=comparisonQuestion('returns');
 const rates=[state.poor,returnComparisonRate??expectedReturn(p),state.strong],names=['Poor','Expected','Strong'],keys=['poor','expected','strong'];
 const heading=question==='spending'?'How do returns change what you can withdraw?':question==='portfolio'?'How do returns change the investments you need?':question==='projection'?'Which returns meet your FI goal?':'How do returns change your FI date?';
 const held=question==='spending'?'Investments, starting cash, deadline, inflation and FI target stay fixed.':question==='portfolio'?'Withdrawal rule, starting cash, deadline, inflation and FI target stay fixed.':'Withdrawal rule, investments, starting cash, inflation and FI target stay fixed.';
 const inputs=`<div class="panel content-panel"><h2>${heading}</h2>${comparisonSelector('returns',question)}<p>${held} Each scenario uses a constant real return; scenarios are not assigned probabilities.</p>${question==='return'?`<p>Your calculated required return is ${percent(expectedReturn(p))} after inflation. Compare lower or higher returns to see how the FI date changes.</p>`:''}<div class="scenario-controls">${field('poor','Poor real return',rates[0]*100,{suffix:'%'})}${field('scenarioExpected','Expected real return',entry(rates[1],100,3),{suffix:'%'})}${field('strong','Strong real return',rates[2]*100,{suffix:'%'})}</div></div>`;
 let comparison;try{comparison=compareReturns(p,rates,question);}catch(e){return inputs+`<div class="notice" role="alert">${e.message}</div>`;}
 const scenarios=comparison.scenarios,valid=scenarios.map((s,i)=>({...s,index:i})).filter(s=>!s.error);
 const rows=valid.length?valid[0].full.rows.map((r,i)=>({year:r.year,...Object.fromEntries(valid.map(s=>[keys[s.index],displayAmount(s.full.rows[i].total,p,r.year)])),target:displayAmount(fiTarget(p),p,r.year)})):[];
 const cards=scenarios.map((s,i)=>{
  if(s.error)return metric(names[i]+' · no solution','Not feasible',s.error);
  const rate=percent(rates[i])+' real return';
  if(question==='spending')return metric(names[i]+' · annual withdrawals',money(s.plan.spending),`${rate} · ${s.plan.withdrawalMode==='dollars'?money(s.plan.spending/12)+' per month':percent(s.plan.withdrawalRate)+' withdrawal rate'} · today’s dollars`);
  if(question==='portfolio')return metric(names[i]+' · required investments',money(s.plan.portfolio),`${rate} · plus ${money(s.plan.cash)} starting cash`);
  if(question==='projection')return metric(names[i],s.onTrack?'On track':'Not on track',`${rate} · ${money(displayAmount(s.projection.end.total,p,p.years))} at your desired date`);
  return metric(names[i]+' · projected FI',s.arrival.error?'Not reached':p.timeEntry==='age'?'Age '+num(p.age+s.arrival.value,1):dateLabel(s.arrival.value),s.arrival.error?s.arrival.error:`${rate} · ${num(s.arrival.value,2)} years · ${dateLabel(s.arrival.value)} · ${s.onTrack?'Meets desired date':'Misses desired date'}`);
 }).join('');
 return inputs+`<h2 class="result-divider">Results</h2>${dollarControls()}<div class="metrics">${cards}</div>${valid.length?`<div class="panel chart-panel"><h2>Total assets under each return assumption</h2><p>${question==='spending'?'Each line uses the annual withdrawals calculated for that return.':question==='portfolio'?'Each line uses the starting investments calculated for that return.':'Each line uses the same investments and withdrawal rule.'} Risk FI withdrawals continue throughout; Your plan shows the switch to Traditional FI withdrawals.</p>${chart('scenario-comparison',rows,[...valid.map(s=>({key:keys[s.index],label:names[s.index],color:['var(--red)','var(--purple)','var(--secondary)'][s.index]})),{key:'target',label:'FI target',color:'var(--muted)',dash:true}])}${valid.length<3?'<p class="chart-caption">Scenarios without a solution are omitted.</p>':''}</div>`:''}`;
}
function withdrawalScenariosView(p){
 const percentage=p.withdrawalMode!=='dollars',base=percentage?p.withdrawalRate:p.spending;
 const values=withdrawalComparisons.mode===p.withdrawalMode&&withdrawalComparisons.values?withdrawalComparisons.values:[base*.8,base,percentage?Math.min(1,base*1.2):base*1.2];
 const names=['Scenario A','Scenario B','Scenario C'],keys=['a','b','c'];
 const question=comparisonQuestion('withdrawals'),heading=question==='portfolio'?'How do withdrawals change the investments you need?':question==='return'?'How do withdrawals change the return you need?':question==='projection'?'Which withdrawals meet your FI goal?':'How do withdrawals change your FI date?';
 const fixedNote=question==='portfolio'?'Starting cash, deadline, returns, inflation and FI target stay fixed.':question==='return'?'Investments, starting cash, deadline, inflation and FI target stay fixed.':'Investments, starting cash, returns, inflation and FI target stay fixed.';
 const inputs=`<div class="panel content-panel"><h2>${heading}</h2>${comparisonSelector('withdrawals',question)}<p>Compare three Risk FI withdrawal ${percentage?'rates':'amounts'}. ${fixedNote}</p><p class="hint">${percentage?p.withdrawalMode==='annual'?'Percentages apply to each year’s opening investments.':'Percentages set the starting annual dollar amount.':'Enter annual amounts in today’s dollars.'} ${p.withdrawalMode==='annual'?'Withdrawals change with the investment balance.':p.adjustWithdrawals?'Withdrawals rise with inflation.':'The nominal withdrawal amount stays fixed.'}</p><div class="scenario-controls">${values.map((v,i)=>field('withdrawalScenario'+i,names[i],entry(v,percentage?100:1,percentage?3:2),percentage?{suffix:'%',min:0,max:100}:{prefix:'$',min:0})).join('')}</div><button id="withdrawal-defaults">Use plan defaults</button><p class="hint">Defaults are 20% less, your plan, and 20% more (rates capped at 100%). Editing these scenarios does not change Your plan.</p></div>`;
 let comparison;try{comparison=compareWithdrawals(p,values,question);}catch(e){return inputs+`<div class="notice" role="alert">${e.message}</div>`;}
 const {scenarios}=comparison;
 const valid=scenarios.map((s,i)=>({...s,index:i})).filter(s=>!s.error);
 const rows=valid.length?valid[0].full.rows.map((r,i)=>({year:r.year,...Object.fromEntries(valid.map(s=>[keys[s.index],displayAmount(s.full.rows[i].total,p,r.year)])),target:displayAmount(fiTarget(p),p,r.year)})):[];
 const cards=scenarios.map((s,i)=>{
  if(s.error)return metric(names[i]+' · no solution','Not feasible',s.error);
  const withdrawals=`${money(s.plan.spending)} initial annual withdrawals in today’s dollars`;
  if(question==='portfolio')return metric(names[i]+' · required investments',money(s.plan.portfolio),`Plus ${money(s.plan.cash)} cash · ${withdrawals}`);
  if(question==='return')return metric(names[i]+' · required return',percent(nominalReturn(expectedReturn(s.plan),p.inflation)),`Before inflation · ${percent(expectedReturn(s.plan))} real · ${withdrawals}`);
  if(question==='projection')return metric(names[i],s.onTrack?'On track':'Not on track',`${withdrawals} · target date ${dateLabel(p.years)}`);
  return metric(names[i]+' · projected FI',s.arrival.error?'Not reached':p.timeEntry==='age'?'Age '+num(p.age+s.arrival.value,1):dateLabel(s.arrival.value),s.arrival.error?s.arrival.error:`${dateLabel(s.arrival.value)} · ${num(s.arrival.value,2)} years · ${s.onTrack?'Meets desired date':'Misses desired date'} · ${withdrawals}`);
 }).join('');
 return inputs+`<h2 class="result-divider">Results</h2>${dollarControls()}<div class="metrics">${cards}</div>${valid.length?`<div class="panel content-panel"><h3>At your desired date · ${dateLabel(p.years)}</h3><div class="metrics">${valid.map(s=>metric(names[s.index]+' total assets',money(displayAmount(s.projection.end.total,p,p.years)),s.projection.unfunded>.01?'Includes unfunded withdrawals.':`FI target: ${money(displayAmount(fiTarget(p),p,p.years))}`)).join('')}</div></div><div class="panel chart-panel"><h2>Total assets under each withdrawal scenario</h2><p>${question==='portfolio'?'Each line uses its required starting investments.':question==='return'?'Each line uses its required return.':'Each line uses the same investments and return.'} Risk FI withdrawal rules continue throughout this comparison; Your plan shows the switch to Traditional FI withdrawals.</p>${chart('withdrawal-scenario-comparison',rows,[...valid.map(s=>({key:keys[s.index],label:names[s.index],color:['var(--red)','var(--purple)','var(--secondary)'][s.index]})),{key:'target',label:'FI target',color:'var(--muted)',dash:true}])}<p class="chart-caption">${nominal?'Future dollars':'Today’s dollars'} · smooth-return projections, not probabilities. Starting cash is held fixed. ${valid.length<3?'Scenarios without a solution are omitted from the graph.':''}</p></div>`:''}`;

}
function checkView(){if(!baseline)return `<div class="panel content-panel"><p class="eyebrow">ANNUAL CHECK-IN</p><h2>Compare with a saved plan</h2><p>Save your current plan as a baseline to preserve its starting investments, cash, spending, return assumptions, and target date. Then compare your position each year.</p><button class="primary" id="save-baseline">Save current plan as baseline</button><p class="chart-caption">The baseline is saved in this browser. Clearing browser data removes it.</p></div>`;
 const b=baseline;const v={date:today,portfolio:state.portfolio,cash:cashAmount(resolveWithdrawals(state)),spending:withdrawalAmount(state),...checkValues};
 return `<div class="panel content-panel"><p class="eyebrow">ANNUAL CHECK-IN</p><h2>1 · Compare planned and current balances</h2><p>Compare today’s position with the saved baseline, then find your updated projection.</p><h3>Your current position</h3><div class="check-grid">${field('checkDate','Check-in date',v.date,{type:'date'})}${field('checkPortfolio','Current investments',v.portfolio,{prefix:'$',min:0})}${field('checkCash','Current cash reserve',v.cash,{prefix:'$',min:0})}${field('checkSpending','Current annual withdrawals',v.spending,{prefix:'$',min:0})}</div><p class="chart-caption">Enter current values in dollars at your check-in date. The original trajectory is converted to that same purchasing power for a fair comparison.</p><details><summary>Edit original baseline</summary><div class="check-grid">${field('originalStart','Original start date',b.start,{type:'date'})}${field('originalTarget','Original target date',dateValue(dateAfter(b.plan.years,b.start)),{type:'date'})}${field('originalPortfolio','Original invested portfolio',b.plan.portfolio,{prefix:'$',min:0})}${field('originalSpending','Original annual withdrawals',b.plan.spending,{prefix:'$',min:0})}${field('originalCash','Original cash reserve',cashAmount(b.plan),{prefix:'$',min:0})}${field('originalReturn','Original real return',+(expectedReturn(b.plan)*100).toFixed(4),{suffix:'%'})}</div><p class="chart-caption">Original amounts are in the purchasing power of the original start date. Other saved assumptions remain fixed.</p></details></div><div id="check-results"></div>`;}
function calculateCheck(){if(!baseline||!$('#check-results'))return;try{
 const v={date:today,portfolio:state.portfolio,cash:cashAmount(resolveWithdrawals(state)),spending:withdrawalAmount(state),...checkValues},elapsed=yearsBetween(baseline.start,v.date);if(elapsed<0||elapsed>100)throw Error('The check-in must be within 100 years after the original start.');
 const b=baseline.plan,check=annualCheckIn(b,v,elapsed),{factor:f,original,planned,delta,remaining,plan:p,spending:spend,requiredReturn:ret,time,status}=check;
 const rows=project(b,{years:Math.max(b.years,elapsed)}).rows.map(r=>({year:r.year,investment:r.investment*f,cash:r.cash*f}));
 $('#check-results').innerHTML=`<h2 class="result-divider">2 · Results</h2><div class="answer"><p class="eyebrow">ANNUAL CHECK-IN</p><h2>${status}</h2><p class="sub">${money(v.portfolio)} invested vs ${money(planned)} on the original projection · ${delta>=0?'+':''}${percent(delta)}</p></div><div class="metrics">${metric('Updated withdrawal limit',spend.error?'No solution':money(spend.value),'To the original target date')}${metric('New projected FI date',time.error?'Not reached':dateLabel(time.value,v.date),time.error?time.error:num(time.value,2)+' years from check-in')}${metric('Required real return',ret.error?'No solution':percent(ret.value),'To the original target date')}</div><div class="notice"><strong>Current withdrawals / investments: ${percent(v.portfolio?v.spending/v.portfolio:null)}.</strong> ${time.error?time.error:time.value>remaining?`Your new FI date is ${dateLabel(time.value,v.date)}, ${num(time.value-remaining,2)} years later than the original target.`:'Your plan reaches FI by the original target date.'} “On track” means investments are within 5% of the original projection. Cash is shown separately.</div><div class="panel chart-panel"><h2 style="font-size:1rem">Original plan and your actual position</h2>${chart('annual-check-in',rows,[{key:'investment',label:'Original investments',color:'var(--purple)'},{key:'cash',label:'Original cash',color:'var(--red)'}],{point:{year:elapsed,value:v.portfolio},start:baseline.start})}<p class="chart-caption">Orange dot: actual investments at check-in · X axis: years from original start · values in check-in-date dollars. Current cash: ${money(v.cash)}; planned cash: ${money(original.end.cash*f)}.</p></div>`;drawCharts();
 }catch(e){$('#check-results').textContent=e.message;}}
function methodView(){return `<div class="panel content-panel"><h2>Start with your plan</h2><p>Choose the question you want answered. Then enter your investments, withdrawals now, and withdrawal goal once you reach FI.</p><h3>Two withdrawal amounts</h3><p><strong>Withdrawals now</strong> come out of your portfolio while you work toward FI. <strong>Withdrawals once you reach FI</strong> set your target. At 4%, $100,000 a year means a $2.5 million total-assets target.</p><h3>Then explore Risk-Based Guardrails</h3><p>Markets vary. Guardrails reduce or increase withdrawals when your estimated chance of reaching the goal crosses your chosen limits. A schedule can raise those limits over time.</p><h3>Two different probabilities</h3><p><strong>Chance if withdrawals stay unchanged:</strong> the estimate used to decide whether an adjustment is needed. <strong>Reached FI on time:</strong> the share of simulations that succeeded while following the adjustment rules.</p><p>All amounts default to today’s purchasing power. Projections depend on assumptions; probability targets are not guarantees.</p></div><details class="panel content-panel"><summary>Calculation details and assumptions</summary>${detailedMethodView()}</details>`;}
function detailedMethodView(){return `<div><h3>Targets and inflation</h3><p>Inputs are today’s dollars. Traditional FI withdrawals divided by the selected FI rate set a target in today’s purchasing power. Investments plus cash count toward that target. Future dollars multiply each amount by (1 + inflation) raised to years elapsed. Changing display units never changes the solution.</p><h3>Withdrawals</h3><p>Dollar withdrawals and starting-investment percentages can rise with inflation or stay fixed in nominal dollars. Each-year percentages use opening investments without an added inflation increase. After FI, withdrawals switch to your Traditional FI amount, converted to dollars at that date; your inflation choice applies thereafter. The FI target itself always keeps its purchasing power.</p><h3>Cash</h3><p>Reserve only leaves cash untouched. Spend cash first uses cash above the minimum before investments. The downturn buffer uses cash in periods with negative real investment returns. Cash earns its own return and is not automatically replenished. Untouched cash can count toward FI even when the chosen withdrawal policy leaves withdrawals unfunded.</p><h3>Timing</h3><p>Returns compound before period-end withdrawals. Fractional periods prorate withdrawals. The projection includes the FI crossing and continues for the selected years, capped at 100 years total. Reaching FI does not guarantee subsequent withdrawals can be funded.</p><h3>Returns</h3><p>Real return = (1 + return before inflation) ÷ (1 + inflation) − 1. Return scenarios are smooth projections, not probabilities. Include fees and investment taxes in your return assumption and withdrawal taxes in your withdrawal amount.</p><h3>Separate guardrail model</h3><p>Risk-Based Guardrails shares your plan’s amounts, returns and inflation choice. It uses historical market samples, total-assets goals and probability-based withdrawal adjustments. Its cash reserve refills after positive stock years. Compare withdrawal rules within that tab.</p><h3>Saved data</h3><p>Entries stay in this browser. No financial inputs are sent to a server.</p></div>`;}
function bindView(){
 for(const kind of ['withdrawals','returns','dates']){const el=$('#compare-question-'+kind);if(el)el.onchange=()=>{comparisonQuestions[kind]=el.value;persist();update();};}
 for(let i=0;i<3;i++){const el=$('#targetScenario'+i);if(el)el.onchange=()=>{const p=resolved,years=targetHorizons?[...targetHorizons]:[Math.max(1,p.years-5),Math.max(1,p.years),Math.min(100,Math.max(1,p.years)+5)];years[i]=el.value===''?null:p.timeEntry==='age'?readNumber(el.value)-p.age:yearsBetween(today,el.value);targetHorizons=years;persist();update();};}
 $('#target-defaults')?.addEventListener('click',()=>{targetHorizons=null;persist();update();});

 if($('#asset-chart-view'))$('#asset-chart-view').onchange=e=>{assetChartView=e.target.value;update();$('#asset-chart-view')?.focus({preventScroll:true});};
 $$('[data-projection-horizon]').forEach(el=>el.onchange=()=>{const id=el.id;state.afterFIYears=Number(el.value);persist();update();$('#'+id)?.focus({preventScroll:true});});
 for(let i=0;i<3;i++){const el=$('#withdrawalScenario'+i);if(el)el.oninput=()=>{const percentage=resolved.withdrawalMode!=='dollars',base=percentage?resolved.withdrawalRate:resolved.spending,values=withdrawalComparisons.mode===resolved.withdrawalMode&&withdrawalComparisons.values?[...withdrawalComparisons.values]:[base*.8,base,percentage?Math.min(1,base*1.2):base*1.2],value=readNumber(el.value);values[i]=value===null?null:value/(percentage?100:1);withdrawalComparisons={mode:resolved.withdrawalMode,values};persist();clearTimeout(scenarioTimer);scenarioTimer=setTimeout(()=>{update();$('#withdrawalScenario'+i)?.focus();},500);};}
 $('#withdrawal-defaults')?.addEventListener('click',()=>{withdrawalComparisons={mode:null,values:null};persist();update();});
 $$('[data-dollars]').forEach(b=>b.onclick=()=>{nominal=b.dataset.dollars==='nominal';update();persist();});
 for(const id of ['poor','strong','scenarioExpected','riskMean']){const el=$('#'+id);if(el)el.oninput=()=>{clearTimeout(scenarioTimer);scenarioTimer=setTimeout(()=>{const value=readNumber(el.value)/100;if(id==='scenarioExpected'){returnComparisonRate=value;}else if(id==='riskMean'){state={...state,returnMode:'nominal',nominal:nominalReturn(value,state.inflation)};unknown='projection';}else state[id]=value;riskOutput=null;update();rebuildInputs();persist();const next=$('#'+id);next?.focus();},450);};}
 $('#save-baseline')?.addEventListener('click',saveBaseline);
 for(const [id,key]of Object.entries({checkDate:'date',checkPortfolio:'portfolio',checkCash:'cash',checkSpending:'spending'})){const el=$('#'+id);if(el)el.oninput=()=>{checkValues[key]=key==='date'?el.value:readNumber(el.value);calculateCheck();};}
 for(const id of ['originalStart','originalTarget','originalPortfolio','originalSpending','originalCash','originalReturn']){const el=$('#'+id);if(el)el.oninput=()=>{if(id==='originalStart'){const end=$('#originalTarget').value;baseline.start=el.value;baseline.plan.years=Math.max(0,yearsBetween(el.value,end));}else if(id==='originalTarget')baseline.plan.years=Math.max(0,yearsBetween(baseline.start,el.value));else if(id==='originalReturn'){baseline.plan.returnMode='real';baseline.plan.real=readNumber(el.value)/100;}else if(id==='originalCash'){baseline.plan.cashMode='dollars';baseline.plan.cash=readNumber(el.value);}else{baseline.plan[id==='originalPortfolio'?'portfolio':'spending']=readNumber(el.value);if(id==='originalSpending')baseline.plan.withdrawalMode='dollars';}calculateCheck();persist();};}
}
function update(){renderSectionTools();renderToolSetup();if(!['guardrails','position'].includes(tab))leaveGuardrails();$('.workspace').dataset.view=tab;charts=[];worker?.terminate();clearTimeout(riskTimer);try{
 if(['guardrails','position'].includes(tab)){const shared=unknown==='projection'?{plan:{...state}}:solve(state,unknown);if(shared.error)throw Error(shared.error);connectGuardrailPlan({...guardrailPlanInputs(resolveWithdrawals(shared.plan)),sourceSolved:unknown},()=>navigate('numbers'),nominal,value=>{nominal=value;persist();},(key,value)=>{const current=unknown==='projection'?{plan:{...state}}:solve(state,unknown);if(current.error)throw Error(current.error);state=editConnectedPlan(resolveWithdrawals(current.plan),key,value);unknown='projection';persist();rebuildInputs();update();});$('#error').hidden=true;mountGuardrails($('#view'),{mode:tab==='position'?'check':'compare',usePlan:()=>{const solved=unknown==='projection'?{plan:{...state}}:solve(state,unknown);if(solved.error)throw Error(solved.error);return guardrailPlanInputs(resolveWithdrawals(solved.plan));}});return;}
 if(state.timeEntry==='age'&&(!Number.isFinite(state.age)||state.age<0||state.age>120)&&tab==='plan')throw Error('Enter a current age between 0 and 120.');
 if(tab==='numbers'){$('#error').hidden=true;$('#view').innerHTML='';syncSolved();return;}
 if(tab==='gap'){renderGap();return;}
 if(tab==='method'){ $('#error').hidden=true;$('#view').innerHTML=methodView();return;}
 if(tab==='checkin'){ $('#error').hidden=true;$('#view').innerHTML=checkView();bindView();calculateCheck();return;}
 const sol=unknown==='projection'?{plan:{...state}}:solve(state,unknown);if(sol.error){$('#error').hidden=true;$('#view').innerHTML=`<div class="answer"><p class="eyebrow">${labels[unknown]||'Your plan'}</p><h2 class="plan-status">${unknown==='time'?'Traditional FI is not reached':'No solution with these inputs'}</h2><p class="sub">${sol.error}</p></div>`;syncSolved();return;}resolved=resolveWithdrawals(sol.plan);currentProjection=project(resolved);$('#error').hidden=!sol.error;$('#error').textContent=sol.error||'';
 $('#view').innerHTML=tab==='plan'?planView(resolved,currentProjection,sol):tab==='scenarios'?scenariosView(resolved):tab==='withdrawals'?withdrawalScenariosView(resolved):tab==='dates'?targetDatesView(resolved):tab==='checkin'?checkView():methodView();syncSolved();drawCharts();bindView();
 if(tab==='checkin')calculateCheck();
 }catch(e){$('#error').hidden=false;$('#error').textContent=e.message;$('#view').innerHTML='<div class="panel content-panel"><h2>Check your inputs</h2><p>Check the missing or invalid values in Your numbers.</p><button id="fix-numbers">Edit your numbers</button></div>';$('#fix-numbers').onclick=()=>navigate('numbers');}}
function saveBaseline(){baseline={start:today,plan:{...resolved}};checkValues={};persist();toast('Baseline saved in this browser.');if(tab==='checkin')update();}
$('#theme').onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('riskfi-theme',t);}catch{}};
function navigate(next){tab=next;const main=['scenarios','withdrawals','dates','risk'].includes(tab)?'plan':tab==='checkin'?'position':tab;$$('nav [data-tab]').forEach(t=>t.classList.toggle('active',t.dataset.tab===main));update();}
function renderSectionTools(){const host=$('#section-tools');host.innerHTML=['plan','scenarios','withdrawals','dates','risk'].includes(tab)?`<button data-tab="plan">Plan calculator</button><button data-tab="withdrawals">Compare withdrawal scenarios</button><button data-tab="scenarios">Compare return scenarios</button><button data-tab="dates">Compare target dates</button>`:['position','checkin'].includes(tab)?`<button data-tab="position">Withdrawal check</button><button data-tab="checkin">Compare with saved plan</button>`:'';host.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.onclick=()=>navigate(b.dataset.tab);});}
$$('nav [data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));
$('#reset').onclick=()=>{state=simplifyPlan({...defaults,separateFiWithdrawals:true});unknown='spending';riskOutput=null;update();rebuildInputs();persist();toast('Assumptions reset. Your saved baseline is preserved.');};

update();renderInputs();
$('#show-riskfi').onclick=()=>navigate('plan');
// Optional progressive enhancement. Ordinary browsers need no agent APIs.
try{document.modelContext?.registerTool({name:'read_risk_fi_plan',description:'Read the current calculator assumptions and projected result without changing the plan.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input)=>{if(input&&Object.keys(input).length)throw Error('This read-only tool accepts no parameters.');return ({assumptions:resolved,endingInvestments:currentProjection?.end.investment,fiTarget:currentProjection?.target,arrival:outcome(resolved)});}});}catch{}

function sharedCards(p,scope){
 const row=(key,label,value,percentValue=false,calculated=false)=>`<div class="shared-row"><label for="${scope}-${key}">${label}</label>${calculated?'<span class="hint">Calculated in results</span>':`<input id="${scope}-${key}" data-shared="${key}" ${percentValue?'type="number" step="any"':'type="text" inputmode="decimal" data-amount="true"'} value="${Number.isFinite(value)?percentValue?entry(value,100):formatAmount(value):''}">`}</div>`;
 const solving=scope==='riskfi';
 return `<div class="summary-grid shared-cards"><section class="summary-group"><h3>Starting numbers</h3>${row('portfolio','Investments ($)',p.portfolio,false,solving&&unknown==='portfolio')}${row('cash','Cash reserve ($)',cashAmount(p))}${scope==='riskfi'?(p.withdrawalMode==='dollars'?row('spending','Annual RiskFi withdrawals ($)',withdrawalAmount(p),false,unknown==='spending'):row('withdrawalRate',p.withdrawalMode==='annual'?'Annual portfolio withdrawals (%)':'Starting portfolio withdrawals (%)',p.withdrawalRate,true,unknown==='spending')):''}${row('fiWithdrawals','Annual withdrawals at FI ($)',p.fiWithdrawals)}${row('fiRate','FI withdrawal rate (%)',p.fiRate,true)}<div class="shared-row"><span>FI target · today’s dollars</span><strong>${money(fiTarget(p))}</strong></div></section><section class="summary-group"><h3>Assumptions</h3>${row('nominal','Return before inflation (%)',p.nominal,true,solving&&unknown==='return')}${row('inflation','Inflation (%)',p.inflation,true)}${row('cashNominal','Cash yield (%)',p.cashNominal,true)}${p.timeEntry==='age'?row('age','Current age',p.age):''}${scope==='riskfi'?(p.timeEntry==='age'?row('targetAge','Target FI age',Number.isFinite(p.years)?p.age+p.years:null,false,unknown==='time'):row('years','Years to FI',p.years,false,unknown==='time')):''}<p class="hint">Shared with Your numbers.${scope==='gap'&&['portfolio','return'].includes(unknown)?' '+(unknown==='portfolio'?'Investments':'Return')+' calculated by RiskFi.':''}</p></section></div>`;
}
function bindSharedCards(scope,p){
 $$('#'+(scope==='gap'?'view':'tool-setup')+' [data-shared]').forEach(el=>{el.oninput=()=>{
 const key=el.dataset.shared,value=readNumber(el.value),isRate=['nominal','inflation','cashNominal','fiRate','withdrawalRate'].includes(key);
 // Materialize a calculated value only when the user explicitly edits it.
 if(key==='targetAge')state.years=yearsToAge(state.age,value);
 else state[key]=value===null?null:value/(isRate?100:1);
 if(key==='cash')state.cashMode='dollars';
 if(key==='spending')state.withdrawalMode='dollars';
 if(scope==='gap'&&({portfolio:'portfolio',nominal:'return',spending:'spending',years:'time'}[key]===unknown)){
 state={...p,[key]:state[key]};unknown='projection';
 }
 persist();rebuildInputs();
 };el.onblur=()=>update();});
}
function renderToolSetup(){
 const host=$('#tool-setup');host.hidden=tab!=='plan';if(tab!=='plan'){host.innerHTML='';return;}
 let solution;try{solution=unknown==='projection'?{plan:state}:solve(state,unknown);}catch{solution={plan:state};}const p=resolveWithdrawals(solution.plan||state);
 host.innerHTML=`<section class="panel content-panel"><h2>Solve for</h2>${select('riskfi-solve','What would you like to find?',labels,unknown)}${sharedCards(p,'riskfi')}</section>`;
 $('#riskfi-solve').onchange=e=>{unknown=e.target.value;persist();rebuildInputs();update();};bindSharedCards('riskfi',p);
}
function renderGap(){
 let solved;try{solved=unknown==='projection'?{plan:state}:solve(state,unknown);}catch{solved={error:'Check shared inputs.'};}
 if(solved.error&&['portfolio','return'].includes(unknown))throw Error('Your numbers must have a valid solution for investments and return before projecting GapFi.');
 const p=resolveWithdrawals(solved.plan||state);
 const amounts=(v,y=0)=>money(nominal?toNominal(v,p.inflation,y):v);
 $('#error').hidden=true;
 $('#view').innerHTML=`<section class="panel content-panel"><h2>When will you reach FI with gaps in withdrawals or contributions?</h2><p>Choose what happens during each period. The last period continues until FI.</p>${sharedCards(p,'gap')}<p class="hint">GapFi uses the periods below instead of RiskFi withdrawals.</p></section>
 <section class="panel content-panel"><h2>Your periods</h2><p class="hint">Annual amounts start in today’s dollars.</p><div class="gap-periods">${gapPeriods.map((period,i)=>`<section class="input-group"><h3>Period ${i+1}</h3><div class="segmented">${[['withdraw','Withdraw'],['even','Break even'],['contribute','Contribute']].map(([v,l])=>`<button data-gap-action="${v}" data-index="${i}" aria-pressed="${period.action===v}" class="${period.action===v?'active':''}">${l}</button>`).join('')}</div>${period.action!=='even'?field('gap-amount-'+i,period.action==='withdraw'?'Annual withdrawals':'Annual contributions',period.amount,{prefix:'$',min:0}):'<p>No withdrawals or contributions.</p>'}<div class="segmented"><button data-gap-duration="years" data-index="${i}" class="${period.years!==null?'active':''}">For a period</button><button data-gap-duration="until" data-index="${i}" ${i!==gapPeriods.length-1?'disabled':''} class="${period.years===null?'active':''}">Until FI</button></div>${period.years!==null?field('gap-years-'+i,'Number of years',period.years,{min:1,max:99,step:1}):'<p class="hint">Continues until your total assets reach your FI target.</p>'}${gapPeriods.length>1?`<button class="text-button" data-gap-remove="${i}">Remove period ${i+1}</button>`:''}</section>`).join('')}</div><button id="gap-add">Add period</button><p class="hint">${p.adjustWithdrawals!==false?'Withdrawals and contributions increase with inflation.':'Withdrawals and contributions stay fixed in future dollars.'} Change this choice in Your numbers. Cash follows your selected cash strategy; contributions go into investments.</p></section><section id="gap-results"></section>`;
 bindSharedCards('gap',p);
 const changed=()=>{persist();renderGap();};
 $$('[data-gap-action]').forEach(b=>b.onclick=()=>{gapPeriods[+b.dataset.index].action=b.dataset.gapAction;changed();});
 $$('[data-gap-duration]').forEach(b=>b.onclick=()=>{gapPeriods[+b.dataset.index].years=b.dataset.gapDuration==='until'?null:2;changed();});
 $$('[data-gap-remove]').forEach(b=>b.onclick=()=>{gapPeriods.splice(+b.dataset.gapRemove,1);gapPeriods.at(-1).years=null;changed();});
 $('#gap-add').onclick=()=>{if(gapPeriods.at(-1).years===null)gapPeriods.at(-1).years=2;gapPeriods.push({action:'even',amount:0,years:null});changed();};
 gapPeriods.forEach((period,i)=>{for(const key of ['amount','years']){const el=$('#gap-'+key+'-'+i);if(el)el.oninput=()=>{period[key]=readNumber(el.value);persist();renderGapResults(p,amounts);};}});
 renderGapResults(p,amounts);
}
function renderGapResults(p,amounts){
 charts=[];
 try{
 const result=projectGap(p,gapPeriods),arrival=result.reached;
 const rows=result.rows.map(r=>({...r,total:nominal?toNominal(r.total,p.inflation,r.year):r.total,target:nominal?toNominal(r.target,p.inflation,r.year):r.target}));
 $('#gap-results').innerHTML=`<h2 class="result-divider">Your GapFi results</h2><section class="panel content-panel"><h2>${result.shortfall!==null?'Withdrawals cannot be fully funded':arrival===null?'FI is not reached within 100 years':arrival===0?'You have reached your FI target':`FI in ${num(arrival,2)} years · ${dateLabel(arrival)}${p.timeEntry==='age'?' · Age '+num(p.age+arrival,1):''}`}</h2><p>${result.shortfall!==null?'A withdrawal shortfall occurs in '+dateLabel(result.shortfall)+'. The projection stops there.':arrival===null?'These periods do not reach the target within the projection limit.':'Total assets include investments and cash. Arrival is checked monthly.'}</p><div class="segmented"><button data-gap-dollars="real" class="${!nominal?'active':''}">Today’s dollars</button><button data-gap-dollars="nominal" class="${nominal?'active':''}">Future dollars</button></div><p>FI target: <strong>${money(result.target)} in today’s dollars</strong>${arrival!==null?' · '+money(toNominal(result.target,p.inflation,arrival))+' at FI':''}.</p>${chart('gap-assets',rows,[{key:'total',label:'Total assets',color:'var(--purple)'},{key:'target',label:'FI target',color:'var(--muted)',dash:true}],{marker:arrival,boundaries:result.boundaries})}<p class="hint">Dotted lines mark period changes. Constant returns; withdrawals and contributions occur monthly. This is a projection, not a probability of success. The last row may cover part of a year.</p></section><section class="panel content-panel"><h2>Year by year</h2><div class="table-scroll"><table><thead><tr><th>${p.timeEntry==='age'?'Age':'Year'}</th><th>Period</th><th>Withdrawals</th><th>Contributions</th><th>Total assets</th><th>FI target</th></tr></thead><tbody>${result.rows.map(r=>`<tr><td>${num(p.timeEntry==='age'?p.age+r.year:r.year,2)}</td><td>${r.year===0?'Start':r.period+1}</td><td>${nominal?money(r.nominalWithdrawals):money(r.withdrawals)}</td><td>${nominal?money(r.nominalContributions):money(r.contributions)}</td><td>${amounts(r.total,r.year)}</td><td>${amounts(r.target,r.year)}</td></tr>`).join('')}</tbody></table></div></section>`;
 $$('[data-gap-dollars]').forEach(b=>b.onclick=()=>{nominal=b.dataset.gapDollars==='nominal';persist();renderGap();});drawCharts();
 }catch(error){$('#gap-results').innerHTML='<div class="panel content-panel" role="alert"></div>';$('#gap-results div').textContent=error.message;}
}
